def extract_regions(r_seps, c_seps, grid):
    # Rows between separators
    r_ranges = [[0, r_seps[0]]]
    for sep in r_seps:
        if r_ranges and r_ranges[-1][1] == sep:
            r_ranges.append([sep+1, len(grid)-1])

    # Cols between separators  
    c_ranges = [[0, c_seps[0]]]
    for sep in c_seps:
        if c_ranges and c_ranges[-1][1] == sep:
            c_ranges.append([sep+1, len(grid[0])-1])

    regions = []
    for ri, (r_start, r_end) in enumerate(r_ranges):
        for ci, (c_start, c_end) in enumerate(c_ranges):
            region = [[grid[r][c] for c in range(c_start, c_end)] for r in range(r_start, r_end)]
            regions.append((ri, ci, region))
    return regions

